{"command":"python3 - <<'PY'
import json
from collections import deque
path='/root/trace.jsonl'
conf=json.load(open('/root/config.json'))
block_size=conf['block_size']
cap=conf['cache_capacity_blocks']
small_cap=round(cap*conf['s3fifo']['small_ratio'])
main_cap=cap-small_cap
max_freq=conf['s3fifo']['max_freq']
S=deque(); M=deque(); G=deque()
Sfreq={}; Mfreq={}
Sin=set(); Min=set(); Gin=set()

def insert_ghost(h):
    if h in Gin:
        # remove old
        try:
            G.remove(h)
        except ValueError:
            pass
    else:
        if len(G) >= main_cap:
            old=G.popleft(); Gin.remove(old)
    G.append(h); Gin.add(h)

def admit_to_M(h,freq):
    while len(M) >= main_cap:
        victim=M[0]
        vf=Mfreq[victim]
        if vf >= 1:
            M.popleft(); Mfreq[victim]=vf-1; M.append(victim)
        else:
            M.popleft(); Min.remove(victim); del Mfreq[victim]; insert_ghost(victim); break
    M.append(h); Min.add(h); Mfreq[h]=freq

def admit_to_S(h):
    while len(S) >= small_cap:
        victim=S.popleft(); vf=Sfreq.pop(victim); Sin.remove(victim)
        if vf >= 1:
            admit_to_M(victim, vf)
        else:
            insert_ghost(victim)
    S.append(h); Sin.add(h); Sfreq[h]=0

total_prompt=0; total_hit=0; per=[]
for idx,r in enumerate(map(json.loads, open(path))):
    total_prompt += r['input_length']
    # prefix hits
    k=0
    for h in r['hash_ids']:
        if h in Sin or h in Min:
            k += 1
        else:
            break
    hit=min(k*block_size, r['input_length'])
    total_hit += hit
    per.append((idx, r['input_length'], hit, k))
    # access all
    for h in r['hash_ids']:
        if h in Sin:
            Sfreq[h]=min(Sfreq[h]+1,max_freq)
        elif h in Min:
            Mfreq[h]=min(Mfreq[h]+1,max_freq)
        elif h in Gin:
            G.remove(h); Gin.remove(h)
            admit_to_M(h,0)
        else:
            admit_to_S(h)
print('small_cap',small_cap,'main_cap',main_cap)
print('total_prompt',total_prompt)
print('total_hit',total_hit)
print('hit_rate',total_hit/total_prompt)
print('final_blocks',len(S)+len(M))
print('S',len(S),'M',len(M),'G',len(G))
print('0 in', 'S' if 0 in Sin else 'M' if 0 in Min else 'G' if 0 in Gin else 'none', 'freq', Sfreq.get(0,Mfreq.get(0)))
print('first5',per[:5])
print('last5',per[-5:])
